name: vouch

# Author trust signal for this public repo. Phoebe polls this tracker and works
# `ready-for-agent` issues autonomously, so "who filed this?" is worth surfacing
# before anyone — human or agent — spends effort on it.
#
# This workflow is **label-only**. It resolves the author of an issue or PR
# against `.github/VOUCHED.td` via mitchellh/vouch and syncs exactly one managed
# `vouch:*` label onto the thread. It never closes, locks, or blocks anything:
# the gate on Phoebe picking work up is the `ready-for-agent` label, which
# GitHub only lets a triage/write collaborator apply. See docs/trust.md.
#
# Note on `pull_request_target`: it runs in the base-repo context with a
# write-capable token, so a fork PR must never have its code checked out or run
# here. Nothing in this workflow checks out this repo at all — `check-user`
# reads VOUCHED.td over the API — and the only untrusted value that reaches a
# step is an author login, passed through `env:` rather than interpolated into
# a script body.

on:
  pull_request_target:
    types: [opened, reopened, synchronize, ready_for_review, converted_to_draft]
  issues:
    types: [opened, reopened]
  issue_comment:
    types: [created]
  push:
    branches: [main]
    paths:
      - .github/VOUCHED.td
      - .github/workflows/vouch.yml

# Least privilege: read the repo, write labels. Labelling a PR goes through the
# issues API (`issues: write`); `pull-requests: write` is what lets the token
# see and act on the PR side of the same thread.
permissions:
  contents: read
  issues: write
  pull-requests: write

jobs:
  collect-targets:
    name: Collect targets
    runs-on: ubuntu-latest
    outputs:
      targets: ${{ steps.collect.outputs.targets }}
    steps:
      # Reduce every trigger to the same shape: a list of {number, user} to
      # label. Issues and PRs are one namespace here — the issues API backs
      # both, so downstream needs no idea which it is holding.
      - id: collect
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            // GitHub caps a matrix at 256 jobs and errors the whole run past
            // that, so the fan-out is truncated deliberately and loudly rather
            // than taking the workflow down on a busy repo.
            const MAX_TARGETS = 256;

            // Sets the job's `targets` output, truncating to the matrix limit
            // first and naming everything it dropped.
            //
            // `listForRepo` returns newest-first, so truncation keeps the newest
            // and the *same* older threads fall off every sweep — re-running does
            // not drain them. That is why the skipped threads are listed by
            // number rather than counted: they will not reconcile themselves, and
            // `/recheck-vouch` on each is how an operator clears them. There is
            // no continuation state here on purpose; the cap exists so that
            // >256 open threads degrades to "most of them" instead of failing the
            // matrix and reconciling none.
            const emitCappedTargets = (targets) => {
              if (targets.length > MAX_TARGETS) {
                const skipped = targets.slice(MAX_TARGETS);
                core.warning(
                  `${targets.length} targets exceeds the ${MAX_TARGETS}-job matrix limit. ` +
                    `Labelling the newest ${MAX_TARGETS}; a re-run would select the same ` +
                    `batch, so comment /recheck-vouch on each of these ${skipped.length} ` +
                    `to reconcile them: ${skipped.map((t) => `#${t.number}`).join(", ")}`,
                );
                targets = targets.slice(0, MAX_TARGETS);
              }
              core.setOutput("targets", JSON.stringify(targets));
            };

            if (context.eventName === "pull_request_target") {
              const pr = context.payload.pull_request;
              emitCappedTargets([{ number: pr.number, user: pr.user.login }]);
              return;
            }

            if (context.eventName === "issues") {
              const issue = context.payload.issue;
              emitCappedTargets([{ number: issue.number, user: issue.user.login }]);
              return;
            }

            // On-demand recheck. The author is re-resolved, not the commenter —
            // this is how a just-vouched contributor gets their existing thread
            // relabelled without a maintainer touching VOUCHED.td again.
            if (context.eventName === "issue_comment") {
              const issue = context.payload.issue;
              const body = context.payload.comment?.body ?? "";
              if (!body.includes("/recheck-vouch")) {
                emitCappedTargets([]);
                return;
              }
              emitCappedTargets([{ number: issue.number, user: issue.user.login }]);
              return;
            }

            // push to main touching VOUCHED.td (or this file): the trust set
            // itself moved, so every open thread's label may now be stale.
            // `issues.listForRepo` returns PRs alongside issues, which is
            // exactly the set we want.
            const open = await github.paginate(github.rest.issues.listForRepo, {
              owner: context.repo.owner,
              repo: context.repo.repo,
              state: "open",
              per_page: 100,
            });

            // A deleted account reads back as a null user ("ghost"); there is
            // nobody left to resolve, and passing null on would fail the whole
            // matrix leg. Drop those and say so.
            const withAuthors = open.filter((item) => item.user?.login);
            if (withAuthors.length < open.length) {
              core.warning(
                `Skipped ${open.length - withAuthors.length} open thread(s) whose author ` +
                  `no longer exists.`,
              );
            }

            emitCappedTargets(withAuthors.map((item) => ({ number: item.number, user: item.user.login })));

  label:
    # Quoted: an unquoted `#` after a space would start a YAML comment.
    name: "Label #${{ matrix.target.number }}"
    needs: collect-targets
    if: ${{ needs.collect-targets.outputs.targets != '' && needs.collect-targets.outputs.targets != '[]' }}
    runs-on: ubuntu-latest
    concurrency:
      # One in-flight label sync per thread. A `synchronize` storm on a PR
      # collapses to the last push rather than racing itself.
      group: vouch-${{ matrix.target.number }}
      cancel-in-progress: true
    strategy:
      # One bad author lookup must not strand the rest of a push-triggered sweep.
      fail-fast: false
      matrix:
        target: ${{ fromJson(needs.collect-targets.outputs.targets) }}
    steps:
      # `allow-fail: true` keeps this advisory: an unvouched author reports via
      # the `status` output instead of turning the step (and the thread's checks)
      # red. Statuses: bot | collaborator | vouched | denounced | unknown.
      #
      # Both actions here are pinned to a commit SHA rather than the floating
      # major tag `ready.yml` uses. This workflow runs on `pull_request_target`
      # holding a token that can write labels, so a re-pointed upstream tag
      # would execute new third-party code against it. Bump deliberately; the
      # trailing comment is the human-readable version.
      - id: vouch
        name: Resolve author trust
        uses: mitchellh/vouch/action/check-user@d66fa29a64600490892131ad87597c30c91fcac4 # v1.5.0
        with:
          user: ${{ matrix.target.user }}
          allow-fail: true
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}

      - name: Sync vouch label
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          TARGET_NUMBER: ${{ matrix.target.number }}
          VOUCH_STATUS: ${{ steps.vouch.outputs.status }}
        with:
          script: |
            const issueNumber = Number(process.env.TARGET_NUMBER);
            const status = process.env.VOUCH_STATUS;

            // The managed set. These three are owned by this workflow: it
            // creates them on first run and reconciles colour/description after,
            // so the labels stay self-explanatory without a manual `gh label`
            // step in anyone's setup runbook.
            const managedLabels = [
              {
                name: "vouch:trusted",
                color: "1f883d",
                description: "Author is trusted by repo permissions or the VOUCHED list.",
              },
              {
                name: "vouch:unvouched",
                color: "fbca04",
                description: "Author is not yet trusted in the VOUCHED list.",
              },
              {
                name: "vouch:denounced",
                color: "d1242f",
                description: "Author is explicitly blocked by the VOUCHED list.",
              },
            ];

            const managedLabelNames = new Set(managedLabels.map((label) => label.name));

            for (const label of managedLabels) {
              try {
                const { data: existing } = await github.rest.issues.getLabel({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  name: label.name,
                });
                // Only PATCH on actual drift. A push-to-main sweep fans out one
                // matrix leg per open thread, and every leg walks this list —
                // writing unconditionally would mean 3N pointless label writes
                // and N concurrent writers on the same three labels.
                if (
                  existing.color !== label.color ||
                  (existing.description ?? "") !== label.description
                ) {
                  await github.rest.issues.updateLabel({
                    owner: context.repo.owner,
                    repo: context.repo.repo,
                    name: label.name,
                    color: label.color,
                    description: label.description,
                  });
                }
              } catch (error) {
                if (error.status !== 404) {
                  throw error;
                }
                try {
                  await github.rest.issues.createLabel({
                    owner: context.repo.owner,
                    repo: context.repo.repo,
                    name: label.name,
                    color: label.color,
                    description: label.description,
                  });
                } catch (createError) {
                  // 422 = another matrix job created it in the gap. Benign.
                  if (createError.status !== 422) {
                    throw createError;
                  }
                }
              }
            }

            // `unknown` is vouch's word for "not in the list"; everything that
            // counts as trust collapses to one label so the signal reads at a
            // glance on the issue list.
            const nextLabelName =
              status === "denounced"
                ? "vouch:denounced"
                : ["bot", "collaborator", "vouched"].includes(status)
                  ? "vouch:trusted"
                  : "vouch:unvouched";

            const { data: currentLabels } = await github.rest.issues.listLabelsOnIssue({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: issueNumber,
              per_page: 100,
            });

            // Exactly one managed label survives; unmanaged labels are left
            // alone, so this never fights a maintainer's triage labels.
            for (const label of currentLabels) {
              if (!managedLabelNames.has(label.name) || label.name === nextLabelName) {
                continue;
              }
              try {
                await github.rest.issues.removeLabel({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: issueNumber,
                  name: label.name,
                });
              } catch (removeError) {
                if (removeError.status !== 404) {
                  throw removeError;
                }
              }
            }

            if (!currentLabels.some((label) => label.name === nextLabelName)) {
              await github.rest.issues.addLabels({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: issueNumber,
                labels: [nextLabelName],
              });
            }

            core.info(`#${issueNumber}: ${status} -> ${nextLabelName}`);
